let r, a, b, t = 0;

function setup() {
	createCanvas(windowWidth, windowHeight);
	r = max(width, height) * 0.4;
	a = 1;
	b = 0;
	noStroke();
	fill("gold"); // "yellow"
}



function draw() {
	background(0, 64);
	translate(width * 0.5, height * 0.5)

	for (let i = 0; i < 10; i++) {
		t += 0.01;
		if (false) {
			x = r * sin(t)
			y = r * sin(2 * t + PI) * 0.5
		} else {
			let c = random() * 0.1 - 0.05;
			let d = random() * 0.1 - 0.05;
			b = sin(frameCount * 0.004)
			x = a * (cos(t) + b) / (1 + sin(t) * sin(t)) * 0.5 + c
			y = d - a * (cos(t) + b) * (cos(t)) * sin(t) / (1 + sin(t) * sin(t))
			x *= r
			y *= r
		}
		circle(x, y, 8);
	}
}
